{"jsonrpc":"2.0","id":3,"result":{"content":[{"type":"text","text":"{
  "status": "basket",
  "note": "This is a prepared basket, not a placed order. Checkout and payment happen on the venue's own page.",
  "venue": {
    "slug": "doppelt-kaese-berlin",
    "name": "Doppelt Käse Laubacher Straße",
    "currency": "EUR",
    "rail": "venue's own rail (FoodAmigos storefront: Adyen/Stripe/PayPal/cash)",
    "deep_link": "https://www.doppelt-kaese-berlin.de/speisekarte/doppeltkase"
  },
  "handoff": {
    "adapter_class": "deep_link_human",
    "capabilities": {
      "menu": true,
      "quote": true,
      "submit": false,
      "status": false
    },
    "human_steps": [
      "the CVM returns the basket and the venue's own deep link; it places nothing",
      "a human places the order on the venue's own rail (its own web store or by telephone)",
      "a human pays the venue on its own rail; the CVM never takes payment",
      "a human records the venue's own order confirmation as the receipt"
    ],
    "payment_authority": {
      "authority": "the human who places the order, on the venue's own rail",
      "cvm_cap_sats": 0
    },
    "idempotency": {
      "key": "venue_slug + basket_sha256 + fulfilment + when",
      "on_duplicate": "the CVM places nothing, so it cannot double-place; the venue's own order record is the authority"
    },
    "receipt": {
      "form": "the venue's own order confirmation on its own rail (order id)",
      "durable": "the venue's own record"
    }
  },
